// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

// reload info total
function getTotal(id) {
    CirebonwebForm.FormFetch('/bahan-order/gettotal', { id }, 'POST', {}).done(function (response) {
        if (!response.success) return;
        $('#RpSubTotal').text(CirebonwebFormat.Rupiah(response.data.subtotal));
        $('#RpOngkir').text(CirebonwebFormat.Rupiah(response.data.ongkir));
        $('#RpTotal').text(CirebonwebFormat.Rupiah(response.data.total));
    });
}

// dataTables
$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${thisUrl}/tabel`,
            type: 'POST'
        },
        autoWidth: false,
        responsive: true,
        searching: false,
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => { simpan(); }, enabled: statusStok === 0 },
            {
                text: 'Reload',
                action: function (e, dt, node, config) {
                    dt.search('').draw();
                    Swal.fire({
                        icon: 'success',
                        title: 'Informasi',
                        text: 'Selesai reload tabel ke kondisi awal',
                        showConfirmButton: false,
                        timer: 1300
                    }).then(function () { dt.ajax.reload(null, true); });
                }
            }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 4, 9], className: 'dt-body-center' },
            { targets: [2, 3, 5], className: 'dt-body-right' },
            { targets: [2, 3, 4, 5], orderable: false },
            { targets: 9, render: function (data) { return statusStok === 0 ? data : 'Null'; } }
        ]
    });

    getTotal(idOrder);

    // Fokus select2 input
    $(document).on('select2:open', () => document.querySelector('.select2-container--open .select2-search__field')?.focus());

    // Event masking format Rupiah ketikan input diketik user
    $('#harga_satuan, #qty').on('input change', function () {
        hitungJumlah();
    });

    // Reset Modal
    $modalDiv.on('shown.bs.modal', function () {
        $('.select2').select2({ dropdownParent: $modalDiv });
        formCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $('.select2.select2-hidden-accessible').select2('destroy');
    });
});

// Get nama bahan berdasarkan tipe mesin
$('#mesin_tipe_id').on('change', function (event, selectedBahanId, callback) {
    var mesinId = $(this).val();
    var $bahan = $('#bahan_id');

    $bahan.prop('disabled', true).empty().append('<option value="">-- Pilih --</option>').val('').trigger('change');
    $('#harga_satuan, #qty').prop('readonly', true);
    resetDetailBahan();

    if (!mesinId) {
        $bahan.prop('disabled', true);
        $('#harga_satuan, #qty').prop('readonly', true);
        if (typeof callback === 'function') callback();
        return;
    }

    $.ajax({
        url: `${thisUrl}/getbahanmesin`,
        type: 'POST',
        data: { mesin_id: mesinId },
        success: function (res) {
            $.each(res, function (i, row) {
                $bahan.append(`<option value="${row.id}" data-lebar="${row.lebar}" data-panjang="${row.panjang}" data-isipaket="${row.isi_paket}" data-satuan1="${row.satuan_1}" data-satuan2="${row.satuan_2}">${row.nama}</option>`);
            });

            $bahan.prop('disabled', false);
            $('#harga_satuan, #qty').prop('readonly', false);

            var bahanId = selectedBahanId || '';
            $bahan.val(bahanId).trigger('change');

            if (typeof callback === 'function') callback();
        }
    });
});

// Event saat pilih nama bahan
$(document).on('change', '#bahan_id', function () {
    var opt = $(this).find(':selected');
    if (!opt.val()) {
        resetDetailBahan();
        return;
    }

    var lebar = CirebonwebFormat.Desimal(opt.data('lebar')) || 0;
    var panjang = CirebonwebFormat.Desimal(opt.data('panjang')) || 0;
    var isi_paket = CirebonwebFormat.Desimal(opt.data('isipaket')) || 0;
    var satuan1 = opt.data('satuan1') || '?';
    var satuan2 = opt.data('satuan2') || '?';
    // var rumus = opt.data('rumus');

    $('.kode_bahan').text(opt.data('kode') || '-');
    $('.ukuran_bahan').val(`${lebar} x ${panjang} m`);
    $('.isi_paket').val(`1 ${satuan2} = ${isi_paket} ${satuan1}`);
    $('.satuan1').text(`/${satuan1}`);
    $('.satuan2').text(`/${satuan2}`);
    $('.satuanQty').text(`${satuan2}`);

    // if (rumus == 0) {
    //     $('.rumus').html(`Harga Paket = Harga Satuan × ${isi_paket} ${satuan1}<br>Jumlah = Harga Paket × Qty Paket`);
    // } else if (rumus == 1) {
    //     $('.rumus').html(`Harga Paket = Harga Satuan × ${isi_paket} ${satuan1}<br>Jumlah = Harga Paket × Qty Paket`);
    // } else {
    //     $('.rumus').text('null');
    // }
});

// Penjumlahan harga paket item
function hitungJumlah() {
    const hargaSatuan = CirebonwebFormat.unRupiah($('#harga_satuan').val()) || 0;
    const qty = $('#qty').val() || 0;
    const isiPaket = CirebonwebFormat.Desimal($('#bahan_id').find(':selected').data('isipaket')) || 0;

    const hargaPaket = hargaSatuan * isiPaket;
    const jumlah = hargaPaket * qty;

    $('#harga_paket').val(CirebonwebFormat.Rupiah(hargaPaket));
    $('#jumlah').val(CirebonwebFormat.Rupiah(jumlah));
}

// reset detail bahan ke default
function resetDetailBahan() {
    $('.kode_bahan, .satuan1, .satuan2, .satuanQty').text('?');
    $('.ukuran_bahan, .isi_paket').val('null');
}

// Fungsi insert dan update
function simpan(id) {
    let $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${thisUrl}/simpan`;
    $('#bahan_order_id').val(idOrder)

    if (id > 0) {
        CirebonwebForm.FormFetch(`${thisUrl}/getid`, { id }, 'POST', {})
            .done(function (response) {
                if (response.success) {
                    $modalTitle.text('Edit Data'); $btnSubmit.text('Update');

                    $formData.find('#id').val(response.data.id);
                    $formData.find('#qty').val(response.data.qty);

                    $formData.find('#mesin_tipe_id')
                        .val(response.data.id_tipe_mesin)
                        .trigger('change', [response.data.bahan_id, function () {
                            $formData.find('#harga_satuan').val(CirebonwebFormat.Rupiah(response.data.harga_satuan));
                            $formData.find('#harga_paket').val(CirebonwebFormat.Rupiah(response.data.harga_paket));
                            $formData.find('#jumlah').val(CirebonwebFormat.Rupiah(response.data.jumlah));

                            formCek.resetInitial();
                            $modalDiv.modal('show');
                        }]);
                }
            });
    } else {
        // $('#id').val('');
        // CirebonwebForm.FormReset($formData);
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        formCek.resetInitial();
        $modalDiv.modal('show');
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            bahan_order_id: { required: true, digits: true },
            bahan_id: { required: true, digits: true }
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;

            const data = $formData.serializeArray();
            data.forEach(function (item) {
                if (['harga_satuan', 'harga_paket', 'jumlah'].includes(item.name)) {
                    item.value = CirebonwebFormat.unRupiah(item.value);
                }
            });

            CirebonwebForm.FormFetch(postUrl, data, 'POST', {
                before_call: function () {
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            })
                .done(function (response) {
                    if (response.success) {
                        $modalDiv.modal('hide');
                        Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                            .then(function () { getTotal(idOrder); $tabelData.DataTable().ajax.reload(null, false); });
                    }
                });

            return false;
        }
    }));
}

function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${thisUrl}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            // getTotal($('#bahan_order_id').val());
            getTotal(idOrder);
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}

function tambahStok(id) {
    Swal.fire({
        icon: 'question',
        title: 'Tambah Stok Bahan?',
        html: 'Seluruh bahan pada order ini akan ditambahkan ke stok. Setelah proses berhasil, rincian order tidak dapat ditambah dan diubah lagi.',
        showCancelButton: true,
        confirmButtonText: 'Ya, Tambah Stok',
        cancelButtonText: 'Batal'
    }).then(function (result) {
        if (!result.isConfirmed) {
            return;
        }

        CirebonwebForm.FormFetch('/bahan-order/tambahstok', { id: id }, 'POST', {
            before_call: function () {
                $('#tambah-stok').attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
            }
        }).done(function (response) {
            if (response.success) {
                Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                    .then(function () { location.reload(); });
            }
        });
    });
}